    public METBundleSysDocuBrandDetailsRegularTmp      bundleSysDocuBrandDetailsRegularTmp;
    public METBundleSalesInvoicePaymentStubTmp         bundleSalesInvoicePaymentStubTmp;

    SalesInvoiceContract contract;
    CustInvoiceJour custInvoiceJour;

}

